function setAssistantMode(mode: AssistantMode) {
  assistantMode.value = mode
}

function runAssistantTool(toolId: string) {
  const tool = assistantTools.find((item) => item.id === toolId)
  if (!tool) return
  assistantMode.value = tool.mode
  submitAssistant(tool.prompt, tool.mode)
}

function runAssistantAgent(agentId: string) {
  const agent = assistantAgents.find((item) => item.id === agentId)
  if (!agent) return
  assistantMode.value = agent.mode
  submitAssistant(agent.prompt, agent.mode)
}

